import math

def multiply(a, b):
    c = [0] * (len(a) + len(b) - 1)
    for i in range(len(a)):
        for j in range(len(b)):
            c[i + j] = c[i + j] + a[i] * b[j]
    return c

def square_root(n):
    # the whole number whose square is n, or -1 if there's none
    if n >= 0 and math.isqrt(n) ** 2 == n:
        return math.isqrt(n)
    return -1

def sx(s):
    # the text of s times x
    if s == 1:
        return "x"
    return f"{s}x"

def quadratic(case, a, b, c):
    # a x^2 + b x + c with a > 0
    print(case)
    s = square_root(a)
    if b == 0 and c < 0 and s != -1 and square_root(-c) != -1:
        t = square_root(-c)
        print(f"  {a}x^2 = ({sx(s)})^2 and {-c} = {t}^2: difference of squares ({sx(s)} - {t})({sx(s)} + {t})")
    elif c > 0 and s != -1 and square_root(c) != -1 and abs(b) == 2 * s * square_root(c):
        t = square_root(c)
        sign = "-"
        if b > 0:
            sign = "+"
        print(f"  ends ({sx(s)})^2 and {t}^2, middle 2 * {s} * {t} = {abs(b)}: perfect square ({sx(s)} {sign} {t})^2")
    else:
        print("  no square pattern")

def cubes(case, s, t):
    # s^3 x^3 + t^3, so a = s x and b = t
    print(case)
    first = [t, s]
    second = [t * t, -s * t, s * s]
    print(f"  (sx + t) is {first}, (s^2 x^2 - st x + t^2) is {second}")
    print(f"  multiply back: {multiply(first, second)}, and s^3 x^3 + t^3 is {[t ** 3, 0, 0, s ** 3]}")

quadratic("Case 1 · a difference of squares: 9x^2 - 25", 9, 0, -25)
quadratic("Case 2 · a perfect square: x^2 - 10x + 25", 1, -10, 25)
quadratic("Case 3 · not a perfect square: x^2 + 6x + 4", 1, 6, 4)
quadratic("Case 4 · a sum of squares: x^2 + 4", 1, 0, 4)
cubes("Case 5 · a sum of cubes: 8x^3 + 27, s = 2, t = 3", 2, 3)
cubes("Case 6 · a difference of cubes: x^3 - 8, s = 1, t = -2", 1, -2)

