n = int(input())
for i in range(n):
    p = int(input())
    q = int(input())
    k = int(input())
    B = -(p + q)
    C = p * q - k
    print(f"B = {B}, C = {C}")
    bound = abs(B) + abs(C)
    found = False
    for u in range(-bound, bound + 1):
        v = B - u
        if u <= v and u * v == C and not found:
            found = True
            if u == v:
                print(f"roots: {-u}")
            else:
                print(f"roots: {-v} {-u}")
    if not found:
        print("roots: none")
